    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
    tmp: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    # Use per-row scalar accumulators to avoid repeatedly writing tmp[i]
    # and y[i] inside the inner loop. This keeps the hot data in registers
    # and reduces memory traffic on tmp and y.
    for i in seq(0, n):
        acc_A: DATA_TYPE
        acc_B: DATA_TYPE

        acc_A = 0.0
        acc_B = 0.0

        # Compute the two dot-products for row i:
        #   acc_A = A[i, :] · x
        #   acc_B = B[i, :] · x
        for j in seq(0, n):
            acc_A += A[i, j] * x[j]
            acc_B += B[i, j] * x[j]

        # Write back the accumulated values. tmp[i] is the same as in the
        # original kernel, and y[i] = alpha * tmp[i] + beta * (B[i, :] · x).
        tmp[i] = acc_A
        y[i] = alpha * acc_A + beta * acc_B

