#   y[i]   = alpha * tmp[i] + beta * sum_j B[i,j] * x[j]
@proc
def kernel_gesummv_base(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
    tmp: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    # Each row i of A and B contributes independently to tmp[i] and y[i].
    # Loops iterate over full matrix and vector domains.
    for i in seq(0, n):
        # Initialize per-row accumulators.
        tmp[i] = 0.0
        y[i] = 0.0
        for j in seq(0, n):
            tmp[i] += A[i, j] * x[j]
            y[i] += B[i, j] * x[j]
        # Final linear combination for this output element.
        y[i] = alpha * tmp[i] + beta * y[i]

# --------------------------------------------------------------------
# Scheduling: improve inner-loop efficiency while preserving semantics.
#
# We tile the inner j loop by a small constant factor and fully unroll
# the tile loop. This:
#   - Preserves the original i-major, j-minor traversal order, keeping
#     row-major accesses to A and B contiguous in memory.
#   - Exposes instruction-level parallelism and makes it easier for
#     the backend to generate SIMD code over the unrolled j-steps.
#   - Handles arbitrary problem sizes n via a guarded remainder loop.
# --------------------------------------------------------------------
kernel_gesummv_scheduled = kernel_gesummv_base

