#    This creates:
#      for j in seq(0, n):
#    -->
#      for jo in ...:
#          for ji in seq(0, 4):
#              ...
#      # plus a small guarded remainder for n % 4 != 0
j = kernel_gesummv_scheduled.find_loop("j")
kernel_gesummv_scheduled = divide_loop(
    kernel_gesummv_scheduled, j, 4, ("jo", "ji"), tail="cut_and_guard"
)

